import logo from './logo.svg';
import './App.css';
import { Router , Routes, Route , Link } from 'react-router-dom';
import Header from './components/common/header/Haeder';
import Nav from './components/common/nav/NavSide';
import NavDir from './components/common/nav/NavDir';

import MainBlog from './components/common/main/MainBlog';
import FlowChart from './components/common/main/FlowChart';
import TestAjax from './components/common/main/test/TestAjax'
import MkViewer from './components/common/main/MkViewer';
import HtmlView from './components/common/main/HtmlView';
import React, { useState, useEffect } from 'react';
import ImgComparison from './etc/imgCompare/ImgComparison'
import ConverterBase from './etc/convertBase/ConverterBase'
import useTabbarView from './utils/useTabbarView';
import parsingList from './utils/parsingList';
import appReport from './utils/appReport';

const TestViewV01 = ({ data }) => {
  return (
    <ul>
      {data.map((item, index) => (
        <li key={index}>
          <strong>Name:</strong> {item.name} <br />
          <strong>Date:</strong> {item.date || 'No date'} <br />
          <strong>Content:</strong>{' '}
          {Array.isArray(item.content) ? (
            <TestViewV01 data={item.content} /> // 재귀적으로 하위 content 출력
          ) : (
            item.content || 'No content' // 문자열 content인 경우 출력
          )}
          <br/>
        </li>
      ))}
    </ul>
  );
};

function App() {
  const mdFilePath = '/myBlog/components/blog/mdList/mkTestJs.md';
  const [filePath, setFilePath] = useState('https://github.com/ordinaryhumanTohappy/testwedding/blob/main/index.html');
  const [pageName, setPageName] = useState(" 자료 관리 사이트 ");

  const [data, setData] = useState(null); // 데이터를 상태로 관리
  const [initialNodes, setInitialNodes] = useState(null);

  //=============================================================
  //외부 함수 생성 list
  //
  const {
    processNode, 
    generatePath, //itemID -> path
    getContent, //itemID -> 내용물
  } = parsingList();

  //1) 전체 데이터 list
  const [openFolders, setOpenFolders] = useState({});
  
  //2) 선택 데이터 
  //const [selectedItem, setSelectedItem] = useState(null); // 선택된 항목 ID 상태
  // const [selectedItemId, setSelectedItemId] = useState(null); // 선택된 항목 ID 상태
  // const [selectedFolderPath, setSelectedFolderPath] = useState(null);
  // 객체 형태로 상태 통합
  const [selectedItem, setSelectedItem] = useState({
    id: null,
    path: null,
  });

  // 개별 상태 업데이트 함수
  const updateSelectedItem = (key, value) => {
    setSelectedItem((prevState) => ({
      ...prevState,
      [key]: value,
    }));
  };
  // 폴더가 선택될 때 경로 업데이트
  const handleSelect = (item ,itemId ,isFolder) => {
    updateSelectedItem( "id" , itemId);
    if (isFolder) { //폴더 
      updateSelectedItem( "path" , itemId);
      setOpenFolders((prevState) => ({
        ...prevState,
        [itemId]: !prevState[itemId], // 폴더 열림/닫힘 토글
      }));
    } else { // 파일 : 클릭시 viewLists 추가
      addViewList({ title: item.name, link: generatePath(itemId, initialNodes) });
    }
  };
    // 폴더가 선택될 때 경로 업데이트
    const resetSelect = (item ,itemId ,isFolder) => {
      updateSelectedItem( "id" , null);
      updateSelectedItem( "path" , null);
    };

  //3) tabbar list
  const {
    viewLists,
    addViewList,
    removeViewList,
    addItemAtPath,
    processTreeNode,
  } = useTabbarView(initialNodes, setInitialNodes);
 



  //=============================================================


  /* 로그인 체크 */
  const [emailCheck,setEmailCheck] = useState();

  /* 로컬스토리지 체크 */
  function loginCheck(){
    let getLocalEmail = localStorage.getItem("emailCheck");
    //로컬 스토리지에 emailCheck 있다면 setEmailCheck을 true / 없다면 false
    if(getLocalEmail){
      setEmailCheck(true)
    }else{
      setEmailCheck(false)
    }
  }
  
  // 외부 JSON 데이터를 불러오는 함수
  const fetchInitialNodes = async () => {
    //배열 -> 합쳐서 사용 
    if(false)
      try {
        const response = await fetch('https://unknowntie.github.io/myblog_back_Public/contents/mdList.json');
        if (!response.ok) {
          throw new Error('데이터를 불러오는 중 오류 발생');
        }
        const result = await response.json();
        const data = result.flatMap(node => processTreeNode(node));
        setInitialNodes(data); // JSON 데이터를 initialNodes로 설정
        setData(result);
      } catch (error) {
        console.error('JSON 데이터를 불러오는 중 오류 발생:', error);
      }
    else
      try {
        //const response = await fetch('https://unknowntie.github.io/myblog_back_Public/contents/mdListV01.json');
        const response = await fetch('https://unknowntie.github.io/myblog_back_Public/contents/linkList.json');
        if (!response.ok) {
          throw new Error('데이터를 불러오는 중 오류 발생');
        }
        const result = await response.json();
        const initialNodes = result.map((node) => processNode(node));
        setInitialNodes(initialNodes);
        setData(result); // 원본 데이터 저장
      } catch (error) {
        console.error('JSON 데이터를 불러오는 중 오류 발생:', error);
      }
  };

  // 컴포넌트가 마운트될 때 데이터를 불러옴
  useEffect(() => {
    fetchInitialNodes();
  }, []);

// 데이터가 로딩 중 표시 
  if (!data) {  return <div>Loading...</div>; }

  return (
    <div className="App">
      <header  className="header"><Header pageName={pageName}/></header>
      <main className='main'>
      {/* <TestViewV01 data={initialNodes} /> */}
      
        <div className="tabbar">
          <div className="tabs">
            {/* 페이지 파일 */}
            {viewLists.map((item, index) => (
            <Link to={item.link} key={index} className="tab">
                {item.title} 
            </Link>
          ))}
          </div>
        </div>

        <div className="container">
          <div className="item">
          <Routes>
            <Route path="/HtmlView" element={<HtmlView htmlCode={filePath}/>}> </Route>
            <Route path="mkTest" element={<MkViewer mdPath={mdFilePath}/>} />
            <Route path="/etc/imgCompare/ImgComparison" element={<ImgComparison mdPath={mdFilePath}/>} />
            <Route path="/etc/convertBase/ConverterBase" element={<ConverterBase mdPath={mdFilePath}/>} />
            <Route path="TestAjax" element={<TestAjax />} />
            <Route path="*" 
              element={<FlowChart initialNodes={initialNodes}  addViewList={addViewList}
                        handleSelect={handleSelect}/>} />
          </Routes> 
          </div>

          <div className="nav">
            <NavDir initialNodes={initialNodes}  addItemAtPath={addItemAtPath}  
                    openFolders={openFolders}
                    selectedItem={selectedItem} handleSelect={handleSelect} resetSelect={resetSelect}
                    addViewList={addViewList}
            />
          </div>

        </div>
      </main>
    </div>
  );
  
}


export default App;

