import { useState } from 'react';

const useTabbarView = (initialNodes, setInitialNodes) => {
  // 초기 viewLists 및 selectedFolderPath 상태 설정
  const [viewLists, setViewList] = useState([
    // { title: 'memoChart', link: '/memoChart' },
    { title: 'mk test (X)', link: '/mkTest' },
    { title: 'TestAjax', link: '/TestAjax' },
    { title: 'ConverterBase', link: '/etc/convertBase/ConverterBase' },
  ]);
  
  // viewLists에 새 항목 추가
  const addViewList = (newItem) => {
    setViewList((prevLists) => {
      const exists = prevLists.some((item) => item.link === newItem.link);
      return exists ? prevLists : [...prevLists, newItem];
    });
  };

  // viewLists에서 항목 삭제
  const removeViewList = (titleToRemove) => {
    setViewList((prevLists) =>
      prevLists.filter((item) => item.title !== titleToRemove)
    );
  };

  // 선택된 경로에 항목 추가
  const addItemAtPath = (item, path) => {
    const addItemToNodes = (nodes, currentPath) => {
      if (currentPath.length === 0) {
        nodes.unshift(item);
        return;
      }
      const [currentIndex, ...remainingPath] = currentPath;
      const targetNode = nodes[currentIndex];
      if (targetNode && Array.isArray(targetNode.content)) {
        addItemToNodes(targetNode.content, remainingPath);
      }
    };

    const updatedNodes = [...initialNodes];
    const pathArray = path ? path.split('-').map((id) => parseInt(id, 10) - 1) : [];
    addItemToNodes(updatedNodes, pathArray);
    setInitialNodes(updatedNodes);
  };

//---
//node 합치기 (현재 미사용)
const processTreeNode = (node, parentIdx = '', parentTitle = '') => {
	// 현재 노드의 idx와 title을 부모에서 전달받은 값과 결합
	const currentIdx = parentIdx ? `${parentIdx}-${node.idx}` : `${node.idx}`;
	const currentTitle = parentTitle ? `${parentTitle}/${node.title}` : `${node.title}`;

	// 파일이거나 자식이 없는 경우 현재 idx와 title만 반환
	if (!node.children || node.children.length === 0) {
		return [{ idx: currentIdx, title: currentTitle , type: node.type, content: node.content }];
	}

	// 자식이 있을 경우 재귀적으로 순회하여 모든 자식 노드 처리
	let result = [];
	node.children.forEach((child) => {
		result = result.concat(processTreeNode(child, currentIdx, currentTitle));
	});

	return result;
};
	//
  // 필요한 모든 상태와 함수를 반환
  return {
    viewLists,
    addViewList,
    removeViewList,
    addItemAtPath,
		processTreeNode
  };
};

export default useTabbarView;
