import React, { useState, useEffect, useCallback } from 'react';
import { ReactFlow, MiniMap, Controls, Background, useNodesState, useEdgesState, addEdge, Handle } from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { useNavigate } from 'react-router-dom';

// 커스텀 노드 컴포넌트
const CustomNode = ({ data }) => {
  const navigate = useNavigate();

  const handleFileClick = (file) => {
    console.log(' clicked:', file);
    if (file.path) {
      navigate(`/${file.path}`);
    }
  };

  return (
    <div style={{ backgroundColor: data.style.backgroundColor, padding: '10px', borderRadius: '5px', position: 'relative' }}>
      <Handle type="target" position="top" style={{ background: '#555' }} />
      
      {/* 폴더 이름 */}
      <div>{data.label}</div>

      {/* 파일 카드 리스트 */}
      {data.files && data.files.map((file, index) => (
        <div
          key={index}
          onClick={() => handleFileClick(file)}
          style={{
            backgroundColor: '#d99',
            padding: '15px',
            borderRadius: '3px',
            marginTop: '5px',
            fontSize: '0.9em',
            color: '#333',
            cursor: 'pointer',
          }}
        >
          <Handle type="target" position="left" style={{ background: '#555', marginRight: '5px' }} />
          {file.name}
          <Handle type="source" position="right" style={{ background: '#555', marginLeft: '5px' }} />
        </div>
      ))}

      <Handle type="source" position="bottom" style={{ background: '#555' }} />
    </div>
  );
};


const nodeTypes = { customNode: CustomNode };

const FlowChart = ({ initialNodes, addViewList, selectedFolderPath, setSelectedFolderPath }) => {

  // 노드와 엣지 상태 관리
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [openFolders, setOpenFolders] = useState({});
  const [selectedItemId, setSelectedItemId] = useState(null);

  // 노드 클릭 시 폴더 열기/닫기 또는 파일 추가
  const onNodeClick = (event, node) => {
    const { data, id } = node;
    const isFolder = Array.isArray(data.files) && data.files.length === 0;

    setSelectedItemId(id);

    if (isFolder) {
      // 폴더 노드 클릭 시 열림/닫힘 토글
      setSelectedFolderPath(id);
      setOpenFolders((prevState) => ({
        ...prevState,
        [id]: !prevState[id],
      }));
    } else if (data.bfile) { // 파일 노드
      // 파일 노드 클릭 시 viewLists에 추가 및 이동
      addViewList({ title: data.label, link: `/${data.path}` });
    }
  };


  // 엣지 연결 처리
  const onConnect = useCallback(
    (params) => setEdges((eds) => addEdge(params, eds)),
    [setEdges]
  );

  // 선택된 폴더 데이터 필터링
  const getSelectedFolderData = (path, nodes) => {
    if (!path) return nodes; // 경로가 없으면 전체 노드 반환
    const pathArray = path.split('-').map((id) => parseInt(id, 10) - 1);
    let currentNode = nodes;
    for (let index of pathArray) {
      if (currentNode[index] && Array.isArray(currentNode[index].content)) {
        currentNode = currentNode[index].content;
      } else {
        return []; // 잘못된 경로일 경우 빈 배열 반환
      }
    }
    return currentNode;
  };

  // 노드와 엣지를 생성하는 함수
  const calculateNodePositions = (orgNodes) => {
    const levelSpacing = 100;
    const siblingSpacing = 400;
    let offsetX = siblingSpacing;
    const edges = [];
    const nodes = [];
    const hasExtension = (name) => /\.[^./]+$/.test(name);
    //노드 위치 지
    const positionNodes = (node, level = 0, positionX = 0, parentId = null) => {
      if (node.name) {
        const isFile = hasExtension(node.name);
        let backgroundColor = level === 0 ? '#88e' : '#9e9';
        backgroundColor = isFile ? '#dbb' : backgroundColor;
        const label = (isFile ? '📄' : '📁') +node.name +` (${node.id})`;

        // 폴더 노드 추가
        if (!isFile) {
          nodes.push({
            id: `${node.id}`,
            position: { x: positionX + offsetX, y: level * levelSpacing },
            data: { label: label, path: node.name, files: [], style: { backgroundColor } },
            type: 'customNode'
          });

          if (parentId) {
            edges.push({
              id: `e${parentId}-${node.id}`,
              source: parentId,
              target: node.id,
            });
          }
        } else {
          // 파일 노드는 부모 폴더에 파일로 포함
          const parentFolder = nodes.find(n => n.id === parentId);
          if (parentFolder) {
            parentFolder.data.files.push({ name: label ,bfile:true, path: node.name });
          }
        }
      }

      if (Array.isArray(node.content)) {
        node.content.forEach((child, index) => {
          child.id = `${node.id}-${index + 1}`;
          if (!hasExtension(child.name) && index !== 0) offsetX += siblingSpacing;
          positionNodes(child, level + (hasExtension(child.name) ? 0 : 1), positionX, node.id);
        });
      }
    };
    orgNodes.forEach((node, index) => {
      node.id = `${index + 1}`;
      positionNodes(node, 0, index * siblingSpacing);
    });

    return { nodes, edges };
  };
  

  // 선택된 폴더에 맞는 노드와 엣지를 설정
  useEffect(() => {
    const filteredNodes = getSelectedFolderData(selectedFolderPath, initialNodes);
    const { nodes: positionedNodes, edges: generatedEdges } = calculateNodePositions([...filteredNodes]);
    setNodes(positionedNodes);
    setEdges(generatedEdges);
  }, [initialNodes, selectedFolderPath, setNodes, setEdges]);

  

  return (
    <div>

      <div style={{ height: '100vh', width: 'auto', backgroundColor:'black' }}>
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onNodeClick={onNodeClick}
          nodeTypes={nodeTypes} 
        >
          <Controls />
          <MiniMap />
          <Background variant="dots" gap={12} size={1} />
        </ReactFlow>
      </div>
    </div>

  );
};

export default FlowChart;
