import React from 'react';
import myStyle from './StyeTypeV01.module.scss';

function HtmlView({ htmlCode }) {
  return (
    <div className={myStyle.container}>
      <div className={myStyle.item1}>
        <div className={myStyle.title}>제목</div>
        <hr />
        <div className={myStyle.date}>{htmlCode}</div>
      </div>
      <div className={myStyle.item2}>
        {/* iframe 내부 HTML을 크기에 맞게 축소하고 높이는 풀로 설정 */}
        <iframe
          src={`${htmlCode}`}  // public 폴더의 경로를 정확하게 지정
          title="HTML Content"
          width="100%"  // iframe 가로 크기
          height="100%"  // iframe 세로 크기, 부모 크기에 맞게 확장
          frameBorder="0"
          style={{
            transform: 'scale(0.8)',  // 콘텐츠를 80%로 축소
            transformOrigin: '0 0',  // 콘텐츠의 왼쪽 상단을 기준으로 축소
            width: '100%',  // iframe의 너비에 맞게 조정
            height: '100vh',  // iframe의 높이를 뷰포트 높이에 맞게 설정
          }}
        />
      </div>
      <div className={myStyle.item3}>3<br /></div>
    </div>
  );
}

export default HtmlView;
