const parsingList =  () => {
	const contentMap = {};

	// 리스트 : json -> 노드 ( 재귀 )
	function processNode(node , parentIdx = '') {
		const currentIdx = parentIdx ? `${parentIdx}-${node.name}` : node.name;

		// node.content가 배열이 아니고 값으로 존재하는 경우, contentMap에 저장
		if (node.content && !Array.isArray(node.content)) {
			contentMap[currentIdx] = node.content;
		}

		return {
			id: currentIdx,
			name: node.name,
			date: node.date,
			content: Array.isArray(node.content)
				? node.content.map((child) => processNode(child, currentIdx))
				: undefined,
		};
	};
	
  // 경로 : itemId -> nodes
  function generatePath(itemId, nodes) {
    const pathParts = [];
    const ids = itemId.split('-').map((id) => parseInt(id, 10) - 1);

    let currentNode = nodes;
    ids.forEach((id) => {
      if (currentNode[id]) {
        pathParts.push(currentNode[id].name);
        currentNode = currentNode[id].content || [];
      }
    });

    return `/${pathParts.join('/')}`;
  }

	function getContent(itemId) {
    return contentMap[itemId] || null;
}

	return {
		processNode,
    generatePath,
		getContent,
  };
}
	

export default parsingList;
