import React, { useState } from 'react';
import myStyle from './NavDir.module.scss';

function NavDir({ initialNodes, addViewList, addItemAtPath, selectedFolderPath, resetSelect , handleSelect}) {
  const [openFolders, setOpenFolders] = useState({});
  const [selectedItemId, setSelectedItemId] = useState(null); // 선택된 항목 ID 상태

  function handleClick(item, itemId, isFolder) {
    handleSelect(item, itemId, isFolder);
    
    // setSelectedItemId(itemId); // 클릭된 항목 ID 설정
    // if (isFolder) { //폴더 
    //   setSelectedFolderPath(itemId); // 선택된 폴더 경로 설정
    //   setOpenFolders((prevState) => ({
    //     ...prevState,
    //     [itemId]: !prevState[itemId], // 폴더 열림/닫힘 토글
    //   }));
    // } else { // 파일 : 클릭시 viewLists 추가
    //   addViewList({ title: item.name, link: generatePath(itemId, initialNodes) });
    // }
  }

  // 경로 생성
  function generatePath(itemId, nodes) {
    const pathParts = [];
    const ids = itemId.split('-').map((id) => parseInt(id, 10) - 1);

    let currentNode = nodes;
    ids.forEach((id) => {
      if (currentNode[id]) {
        pathParts.push(currentNode[id].name);
        currentNode = currentNode[id].content || [];
      }
    });

    return `/${pathParts.join('/')}`;
  }

  // 파일 트리 렌더링
  function renderFileTree(data = initialNodes, parentId = '', level = 1) {
    return data.map((item, index) => {
      const itemId = parentId ? `${parentId}-${index + 1}` : `${index + 1}`;
      const isFolder = Array.isArray(item.content);
      const isSelected = selectedItemId === itemId; // 선택 여부 확인
      return (
        <div key={itemId}>
          <div
            className={`${myStyle.lineDir} ${isFolder ? myStyle.folder : myStyle.file} ${isSelected ? myStyle.selected : ''}`}
            style={{ paddingLeft: `${level * 20}px` }}
            onClick={() => handleClick(item, itemId, isFolder)}
          >
            {/* 파일 아이콘 추가할려면 요기  */}
            {/* <img
              src={isFolder ? '/icons/folder-icon.png' : '/icons/file-icon.png'}
              alt="@"
              className={myStyle.icon}
            /> */}
            <div>{isFolder ? '📁' : '📄'}{item.name + " (" + itemId + ")"}</div>
          </div>

          {isFolder && openFolders[itemId] && (
            <div className={myStyle.children}>
              {renderFileTree(item.content, itemId, level + 1)}
            </div>
          )}
        </div>
      );
    });
  }

  // 새 폴더 및 파일 추가
  const handleAddFolder = () => {
    const newFolder = { name: 'New Folder', content: [] };
    addItemAtPath(newFolder, selectedFolderPath);
  };

  const handleAddFile = () => {
    const newFile = { name: 'New File.txt', content: "File" };
    addItemAtPath(newFile, selectedFolderPath);
  };

  return (
    <div className={myStyle.container}>
      <div className={myStyle.header}>
        <div className={myStyle.buttons}>
          <button className={myStyle.button} onClick={resetSelect}>홈</button>
          <button className={myStyle.button}>검색</button>
          <button onClick={handleAddFolder} className={myStyle.button}>폴더 추가</button>
          <button onClick={handleAddFile} className={myStyle.button}>파일 추가</button>
        </div>
      </div>
      <div className={myStyle.fileList}>
        {renderFileTree(initialNodes)}
      </div>
    </div>
  );
}

export default NavDir;
